# -*- coding: utf-8 -*-
"""Claude API 얇은 래퍼 — 키 있으면 사용, 실패/부재 시 None 반환(폴백 유도).

프롬프트 캐싱 적용: system(페르소나+상품지식)은 매일 재사용되므로 캐시로 비용 절감.
"""
import json
import re

import config

_client = None


def _get_client():
    global _client
    if _client is not None:
        return _client
    if not config.has_llm():
        return None
    try:
        import anthropic
        _client = anthropic.Anthropic(api_key=config.ANTHROPIC_API_KEY)
        return _client
    except Exception as e:  # noqa: BLE001
        print(f"  [LLM] 클라이언트 생성 실패 → 폴백: {e}")
        return None


def available() -> bool:
    return _get_client() is not None


def complete(system: str, user: str, max_tokens: int = 2000):
    """system+user 프롬프트로 Claude 호출. 성공 시 텍스트, 실패 시 None."""
    client = _get_client()
    if client is None:
        return None
    try:
        resp = client.messages.create(
            model=config.ANTHROPIC_MODEL,
            max_tokens=max_tokens,
            system=[{
                "type": "text",
                "text": system,
                "cache_control": {"type": "ephemeral"},   # 프롬프트 캐싱
            }],
            messages=[{"role": "user", "content": user}],
        )
        return "".join(b.text for b in resp.content if getattr(b, "type", "") == "text").strip()
    except Exception as e:  # noqa: BLE001
        print(f"  [LLM] 호출 실패 → 폴백: {e}")
        return None


def complete_json(system: str, user: str, max_tokens: int = 3000):
    """JSON 응답을 기대하고 파싱까지. 실패 시 None."""
    text = complete(system, user, max_tokens)
    if not text:
        return None
    # 코드펜스/잡텍스트 제거 후 첫 JSON 블록 추출
    text = re.sub(r"^```(?:json)?|```$", "", text.strip(), flags=re.MULTILINE).strip()
    m = re.search(r"[\{\[].*[\}\]]", text, re.DOTALL)
    if not m:
        return None
    try:
        return json.loads(m.group(0))
    except json.JSONDecodeError as e:
        print(f"  [LLM] JSON 파싱 실패 → 폴백: {e}")
        return None

