# -*- coding: utf-8 -*-
"""설계사 관점 해석 엔진 — 뉴스를 '설계사 코멘트 + 고객 활용 + 상품/투자 솔루션'으로 변환.

AI 모드(Claude)와 기본 모드(폴백)가 동일한 스키마를 반환한다:
{
  "date", "mode", "headline",
  "top_news": [{title, summary, source, link, comment, use, products:[id]}],
  "hot":      [{title, source, link, comment}],
  "solutions":[{product_id, product_name, why, pitch}]
}
"""
from collections import Counter
from datetime import datetime

import config
import llm

PRODUCTS = {p["id"]: p for p in config.PRODUCTS["products"]}


# ── 상품 지식베이스를 시스템 프롬프트용으로 압축 ──────────────────
def _product_brief() -> str:
    lines = []
    for p in config.PRODUCTS["products"]:
        lines.append(f"- id={p['id']} | {p['이름']} ({p['유형']}) : {p['한줄정의']} "
                     f"[활용: {p['설계사_활용']}]")
    return "\n".join(lines)


def _system_prompt() -> str:
    b = config.BRAND
    return f"""너는 한국의 베테랑 보험 대리점 사업단장 '{b['owner']} {b['title']}'({b['company']})의
콘텐츠 비서다. 매일 경제·보험 뉴스를 '보험설계사 관점'으로 해석해 고객에게 도움이 되도록 가공한다.

[역할]
- 딱딱한 뉴스를 고객이 이해할 수 있는 언어로 풀어준다.
- 각 뉴스가 고객의 '돈·보장·노후'에 어떤 의미인지 연결한다.
- 자연스럽게 상담/상품으로 이어질 실마리를 제시한다.

[연결 가능한 상품·솔루션 (products id로만 참조)]
{_product_brief()}

[반드시 지킬 준법 원칙 — 매우 중요]
- 단정적 판단·수익 보장 표현 금지 ("무조건", "확정 수익", "손해 없음" 등 X).
- 투자상품(변액/펀드/주식/배당)은 원금손실 가능성을 전제로 서술.
- 달러보험은 환리스크를 전제로 서술.
- 세제·한도 수치는 "~수준(기준 확인 필요)"처럼 확정 단정하지 말 것.
- 공포 조장·과장 금지. 정보 제공·상담 유도 톤 유지.

[문체] 따뜻하고 신뢰감 있는 전문가 톤. 고객이 읽기 쉬운 짧은 문장. 이모지 남발 금지."""


def _map_products(text: str) -> list:
    """텍스트에서 상품 매핑키워드가 걸리는 product id 목록."""
    hits = []
    for p in config.PRODUCTS["products"]:
        if any(k.lower() in text.lower() for k in p["매핑키워드"]):
            hits.append(p["id"])
    return hits


# ── AI 모드 ──────────────────────────────────────────────────────
def _run_llm(articles: list, hot: list, today: str):
    def pack(items, n):
        out = []
        for a in items[:n]:
            out.append(f"- [{a['category']}/{a['source']}] {a['title']} :: {a['summary'][:160]}")
        return "\n".join(out)

    user = f"""오늘 날짜: {today}

[수집된 경제·보험 뉴스 (제목 :: 요약)]
{pack(articles, 22)}

위 뉴스에서 오늘 고객에게 전할 가치가 큰 것을 골라 아래 JSON 스키마로만 답하라.
- top_news: 3~5개. summary=한 줄 요약, comment=설계사 관점 해석(1~2문장),
  use=고객이 활용할 포인트(1문장), products=연결 상품 id 배열(위 목록의 id만, 없으면 []).
- hot: 보험 업계 핫이슈 0~3개(comment=설계사 시각 1문장). 없으면 빈 배열.
- solutions: 오늘 뉴스와 연결되는 투자·상품 솔루션 2~3개.
  product_id(위 목록 id), why=지금 이게 왜 타이밍인지(1문장), pitch=고객용 제안 한 줄.
- headline: 오늘 전체를 관통하는 한 줄.

반드시 아래 형식의 JSON만 출력(설명 문장 금지):
{{"headline":"...","top_news":[{{"title":"...","summary":"...","source":"...","link":"","comment":"...","use":"...","products":["isa"]}}],"hot":[{{"title":"...","source":"...","comment":"..."}}],"solutions":[{{"product_id":"irp","why":"...","pitch":"..."}}]}}"""

    data = llm.complete_json(_system_prompt(), user, max_tokens=3500)
    if not data:
        return None

    # link 보정 (LLM은 링크를 모르므로 제목 매칭으로 원문 링크 채움)
    link_by_title = {a["title"]: a["link"] for a in articles}
    for n in data.get("top_news", []):
        if not n.get("link"):
            n["link"] = link_by_title.get(n.get("title", ""), "")
    for h in data.get("hot", []):
        if not h.get("link"):
            h["link"] = link_by_title.get(h.get("title", ""), "")
    # 솔루션 상품명 채우기
    for s in data.get("solutions", []):
        pid = s.get("product_id")
        s["product_name"] = PRODUCTS.get(pid, {}).get("이름", pid or "")
    data["date"] = today
    data["mode"] = "AI"
    return data


# ── 기본 모드(폴백) ──────────────────────────────────────────────
def _run_fallback(articles: list, hot: list, today: str):
    econ = [a for a in articles if a["category"] == "경제"]
    top_src = hot[:2] + econ[:3]
    seen, top_news = set(), []
    for a in top_src:
        if a["title"] in seen:
            continue
        seen.add(a["title"])
        blob = f"{a['title']} {a['summary']}"
        pids = _map_products(blob)
        if a["category"] == "보험":
            comment = "보험업계 동향입니다. 고객의 기존 보장·상품과 비교해 점검 포인트로 활용하세요."
        else:
            comment = "경제 흐름이 고객의 자산·노후 준비에 영향을 주는 이슈입니다."
        use = "고객 상담 시 '요즘 이런 뉴스가 있죠'로 자연스럽게 대화를 여는 소재로."
        if pids:
            use = f"{PRODUCTS[pids[0]]['이름']} 관점에서 설명하면 상담으로 연결됩니다."
        top_news.append({
            "title": a["title"], "summary": a["summary"][:90] or a["title"],
            "source": a["source"], "link": a["link"],
            "comment": comment, "use": use, "products": pids[:2],
        })

    hot_items = [{"title": a["title"], "source": a["source"], "link": a["link"],
                  "comment": "업계 이슈 — 고객 문의 대비용으로 숙지."} for a in hot[:3]]

    # 솔루션: 전체 뉴스에서 가장 많이 걸린 투자 키워드 → 상품
    counter = Counter()
    for a in articles:
        for pid in _map_products(f"{a['title']} {a['summary']}"):
            counter[pid] += 1
    sols = []
    for pid, _ in counter.most_common(3):
        p = PRODUCTS[pid]
        sols.append({"product_id": pid, "product_name": p["이름"],
                     "why": "관련 뉴스가 오늘 여러 건 확인됐습니다.",
                     "pitch": p["한줄정의"]})
    if not sols:  # 뉴스 매칭이 없으면 기본 3종 제시
        for pid in ("isa", "irp", "variable_insurance"):
            p = PRODUCTS[pid]
            sols.append({"product_id": pid, "product_name": p["이름"],
                         "why": "노후·절세 대비 상시 제안 가능한 상품입니다.",
                         "pitch": p["한줄정의"]})

    return {
        "date": today, "mode": "기본",
        "headline": "경제 흐름을 내 고객의 자산·보장 관점으로 정리했습니다.",
        "top_news": top_news, "hot": hot_items, "solutions": sols,
    }


def interpret(collected: dict) -> dict:
    """수집 결과 → 해석 브리핑. AI 우선, 실패 시 폴백."""
    today = datetime.now().strftime("%Y-%m-%d")
    articles, hot = collected["all"], collected["hot"]
    if llm.available():
        print("  [해석] AI 모드 (Claude)")
        data = _run_llm(articles, hot, today)
        if data:
            return data
        print("  [해석] AI 실패 → 기본 모드로 전환")
    else:
        print("  [해석] 기본 모드 (API 키 없음)")
    return _run_fallback(articles, hot, today)


if __name__ == "__main__":
    import collect
    result = interpret(collect.collect())
    print(f"\n모드: {result['mode']} | 헤드라인: {result['headline']}")
    for n in result["top_news"]:
        print(f"\n- {n['title']}\n  코멘트: {n['comment']}\n  활용: {n['use']}\n  상품: {n['products']}")
    print("\n[솔루션]")
    for s in result["solutions"]:
        print(f"- {s['product_name']}: {s['pitch']} ({s['why']})")

# -*- coding: utf-8 -*-
"""카카오톡 '나에게 보내기'(메모 API) 전송 — 개인용 자동 알림.

토큰은 config/kakao_token.json 에 저장(kakao_auth.py로 최초 1회 발급).
access_token 만료(401) 시 refresh_token으로 자동 재발급.
텍스트 템플릿은 200자 제한이라, 브리핑을 190자 이내 다이제스트로 압축해 전송한다.
"""
import json
import os

import requests

import config

TOKEN_PATH = config.CONFIG_DIR / "kakao_token.json"
TOKEN_URL = "https://kauth.kakao.com/oauth/token"
MEMO_URL = "https://kapi.kakao.com/v2/api/talk/memo/default/send"
TEXT_LIMIT = 190  # 카카오 텍스트 템플릿 200자 안전 여유


def _load_token() -> dict:
    if TOKEN_PATH.exists():
        return json.loads(TOKEN_PATH.read_text(encoding="utf-8"))
    return {}


def _save_token(tok: dict):
    TOKEN_PATH.write_text(json.dumps(tok, ensure_ascii=False, indent=2), encoding="utf-8")


def available() -> bool:
    return bool(_load_token().get("access_token"))


def _refresh(tok: dict) -> dict:
    rest_key = os.getenv("KAKAO_REST_API_KEY", "").strip()
    if not (rest_key and tok.get("refresh_token")):
        return tok
    data = {
        "grant_type": "refresh_token",
        "client_id": rest_key,
        "refresh_token": tok["refresh_token"],
    }
    r = requests.post(TOKEN_URL, data=data, timeout=15)
    if r.ok:
        new = r.json()
        tok["access_token"] = new.get("access_token", tok["access_token"])
        if new.get("refresh_token"):
            tok["refresh_token"] = new["refresh_token"]
        _save_token(tok)
        print("  [카카오] 액세스 토큰 갱신됨")
    else:
        print(f"  [카카오] 토큰 갱신 실패: {r.status_code} {r.text[:120]}")
    return tok


def build_digest(brief: dict, link_url: str = "") -> str:
    """브리핑을 190자 이내 카톡 다이제스트로 압축."""
    head = f"[{brief['date'][5:]}] 오늘의 경제·보험 브리핑"
    lines = [head, brief["headline"][:40]]
    budget = TEXT_LIMIT - len("\n".join(lines)) - 2
    for i, n in enumerate(brief.get("top_news", [])[:3], 1):
        item = f"{i}. {n['title'][:32]}"
        if len("\n".join(lines)) + len(item) + 1 > TEXT_LIMIT - 24:
            break
        lines.append(item)
    sols = [s["product_name"].split(" ")[0] for s in brief.get("solutions", [])[:3]]
    if sols:
        tail = "솔루션: " + "·".join(sols)
        if len("\n".join(lines)) + len(tail) + 1 <= TEXT_LIMIT:
            lines.append(tail)
    return "\n".join(lines)[:TEXT_LIMIT]


def send_to_me(brief: dict, link_url: str = "") -> bool:
    tok = _load_token()
    if not tok.get("access_token"):
        print("  [카카오] 토큰 없음 — 전송 건너뜀 (kakao_auth.py로 발급)")
        return False

    text = build_digest(brief, link_url)
    link = {"web_url": link_url, "mobile_web_url": link_url} if link_url else {"web_url": "https://www.kakaocorp.com"}
    template = {
        "object_type": "text",
        "text": text,
        "link": link,
        "button_title": "자세히 보기" if link_url else "확인",
    }

    def _post(access):
        return requests.post(
            MEMO_URL,
            headers={"Authorization": f"Bearer {access}"},
            data={"template_object": json.dumps(template, ensure_ascii=False)},
            timeout=15,
        )

    r = _post(tok["access_token"])
    if r.status_code == 401:  # 만료 → 갱신 후 1회 재시도
        tok = _refresh(tok)
        r = _post(tok.get("access_token", ""))

    if r.ok:
        print("  [카카오] 나에게 보내기 전송 완료")
        return True
    print(f"  [카카오] 전송 실패: {r.status_code} {r.text[:160]}")
    return False


if __name__ == "__main__":
    # 토큰 없이도 다이제스트 미리보기
    import collect
    import insurance_lens
    b = insurance_lens.interpret(collect.collect())
    print("\n--- 카톡 다이제스트 미리보기 ---")
    msg = build_digest(b)
    print(msg)
    print(f"--- {len(msg)}자 ---")
    if available():
        send_to_me(b)

